{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles Rent Stabilization Ordinance allowable rent increase","requirement":"Landlords of RSO units may raise rent only once every 12 months by the allowable rent increase percentage; from February 2, 2026 no additional utility increase and no increase for an added dependent is allowed.","key_value":"once every 12 months","coverage_conditions":"Rental properties first built on or before October 1, 1978, and replacement units; covers apartments, condominiums, townhomes, duplexes, ADUs, JADUs, hotel rooms occupied over 30 days, and mobile homes.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"In condominiums and townhomes the rent amount is not regulated for tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978"]},"exemptions":"Luxury exemption where the landlord establishes the monthly rent charged on or before May 31, 1978.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and relocation assistance","requirement":"A landlord may evict an RSO tenant only for the listed at-fault or no-fault reasons; no-fault evictions require relocation assistance, and any termination notice must be filed with LAHD within three business days of service.","key_value":"30/60-day notice; 3 business days to file","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Give the tenant a 30-day and 60-day written notice (some evictions require 120-day notice or up to a 1-year extension).","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
